SELECT 
FROM volt_session
WHERE session_date = #{date}
  AND venue_code = #{venueCode}
  AND program_no = #{programNo}
  AND status = 'open'
ORDER BY start_time

SELECT 
FROM volt_session

    status = 'open'

        AND session_date = #{date}


        AND session_date >= #{from}


        AND session_date <= #{to}


        AND venue_code = #{venueCode}


        AND coach_id = #{coachId}


        AND program_no = #{programNo}


ORDER BY session_date, start_time, session_code

SELECT 
FROM volt_session
WHERE session_date = #{date}
  AND venue_code = #{venueCode}
  AND program_no = #{programNo}
  AND status = 'open'
  AND booked < capacity
  AND (session_date > #{today} OR start_time > #{now})
ORDER BY start_time
LIMIT 1

